from collections import deque
from math import gcd

def test_all():
    unreachable = []
    for b1 in range(1, 40):
        for b2 in range(1, 40):
            if b1 == b2:
                continue
            g_gcd = gcd(b1, b2)
            for goal in range(1, max(b1, b2) + 1):
                if goal % g_gcd != 0:
                    continue
                for start in ['one', 'two']:
                    # run BFS
                    init = (b1, 0) if start == 'one' else (0, b2)
                    forbid = (0, b2) if start == 'one' else (b1, 0)
                    q = deque([(init, 1)])
                    visited = {init}
                    found = False
                    while q:
                        (a1, a2), steps = q.popleft()
                        if a1 == goal or a2 == goal:
                            found = True
                            break
                        p2 = min(a1, b2 - a2)
                        p1 = min(a2, b1 - a1)
                        nexts = [
                            (b1, a2), (a1, b2), (0, a2), (a1, 0),
                            (a1 - p2, a2 + p2), (a1 + p1, a2 - p1)
                        ]
                        for nxt in nexts:
                            if nxt == (a1, a2) or nxt == forbid or nxt in visited:
                                continue
                            visited.add(nxt)
                            q.append((nxt, steps + 1))
                    if not found:
                        unreachable.append((b1, b2, goal, start))
