python3 -c "
from collections import deque
from math import gcd

def check_ties():
    ambiguities = []
    for b1 in range(1, 30):
        for b2 in range(1, 30):
            if b1 == b2:
                continue
            g_gcd = gcd(b1, b2)
            for goal in range(1, max(b1, b2) + 1):
                if goal % g_gcd != 0:
                    continue
                for start in ['one', 'two']:
                    init = (b1, 0) if start == 'one' else (0, b2)
                    forbid = (0, b2) if start == 'one' else (b1, 0)
                    q = deque([(init, 1)])
                    visited = {init}
                    goal_results_at_depth = {}
                    found_depth = None
                    while q:
                        (a1, a2), steps = q.popleft()
                        if found_depth is not None and steps > found_depth:
                            break

                        # Check goal
                        r = None
                        if a1 == goal:
                            r = (steps, 'one', a2)
                        elif a2 == goal:
                            r = (steps, 'two', a1)

                        if r is not None:
                            if found_depth is None:
                                found_depth = steps
                            goal_results_at_depth.setdefault(steps, set()).add(r)
                            continue

                        p2 = min(a1, b2 - a2)
                        p1 = min(a2, b1 - a1)
                        nexts = [
                            (b1, a2), (a1, b2), (0, a2), (a1, 0),
                            (a1 - p2, a2 + p2), (a1 + p1, a2 - p1)
                        ]
                        for nxt in nexts:
                            if nxt == (a1, a2) or nxt == forbid or nxt in visited:
                                continue
                            visited.add(nxt)
                            q.append((nxt, steps + 1))

                    if found_depth in goal_results_at_depth:
                        results = goal_results_at_depth[found_depth]
                        if len(results) > 1:
                            ambiguities.append((b1, b2, goal, start, results))

    print('Total ambiguities:', len(ambiguities))
    if ambiguities:
        for item in ambiguities[:10]:
            print(item)

check_ties()
"

